INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d1355da27db0b773c786b11815d5b346a3806769/content/books/zizhi-tongjian/vol-293/year-0956/part-06/sources/library/jiuwudaishi-116-august-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002759；EPUB电子本，纸本及异文待核", "id": "bb4b65cf-a17a-5c68-9f97-439787f5d3dd"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d1355da27db0b773c786b11815d5b346a3806769/content/books/zizhi-tongjian/vol-293/year-0956/part-06/sources/library/jiuwudaishi-116-october-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002761；EPUB电子本，纸本及异文待核", "id": "d6f77a98-15c3-58b0-9b42-f35ee3e47e8d"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d1355da27db0b773c786b11815d5b346a3806769/content/books/zizhi-tongjian/vol-293/year-0956/part-06/sources/library/jiuwudaishi-116-september-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002760；EPUB电子本，纸本及异文待核", "id": "635e221a-5dae-59a9-a2b0-b5ae7fbdea32"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/tongjian-293-956-hunan-yangzhou-withdrawal/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003479；电子底本待考，分段待核", "id": "c976d062-2cad-52b8-b653-331b40f65e06"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "王处讷", "aliases": ["王處訥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周司天少监。956年八月，《资治通鉴》记他与王朴编成《显德钦天历》并呈交朝廷，柴荣下令次年实行。生卒年未载，与邓处讷分别保存。", "biography": null, "status": "draft", "id": "1e577a1c-4f9e-56b3-872d-a578d6f1c141"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "林仁肇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建州人，林仁翰的弟弟。956年由潘承祐荐任南唐将领。生卒年及后续军务待按编年续录。", "biography": null, "status": "draft", "id": "2cf3602b-35b9-55d1-b352-323aa860d16a"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "王彦升", "aliases": ["王彥升"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蜀人，后周铁骑都指挥使。956年十月李重进奏报他等人在盛唐击败南唐军。《资治通鉴》记斩首三千余级，《旧五代史》本纪记二千级，战果数量有异。生卒年本段未载。", "biography": null, "status": "draft", "id": "71fb410e-b404-5f2a-bed1-42a3cc68e1e0"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "宋齐丘主张放周军撤退，南唐命各将守地而不擅出击", "start_year": 956, "end_year": 956, "time_original": "956年七月周军撤离扬州以后，八月历法条以前，具体日未载", "dynasty": "五代十国", "description": "南唐诸将请求据险截击周军，宋齐丘认为这样会加深敌意，主张放其离去，以便缓和战争。南唐随后命各将各守驻地，不得擅自出击；这只是宋齐丘的判断，不能写成双方已经达成和议。", "phases": [], "location_name": "南唐军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "db9a1f1c-3487-51a9-b6d6-055c6a709da7"}, {"title": "徐景达驻濠州声援寿州，陈觉掌军政而未决战", "start_year": 956, "end_year": 956, "time_original": "956年寿春围攻期间，具体驻军日未载", "dynasty": "五代十国", "description": "《资治通鉴》认为停止出击使寿春围势更紧。齐王徐景达驻濠州，遥援寿州，拥兵五万；军政由陈觉决定，徐景达只在文书末尾签署。史书称其没有决战意图、将吏畏惧陈觉而不敢进言；这些评价保留出处，不外推所有人的内心。", "phases": [], "location_name": "濠州、寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "db2b3182-ebca-5f9a-8630-b6e444903644"}, {"title": "王朴、王处讷呈交《显德钦天历》，柴荣令次年实行", "start_year": 956, "end_year": 956, "time_original": "956年八月戊辰呈交；诏令规定次年实行", "dynasty": "五代十国", "description": "王朴、王处讷呈交《显德钦天历》，柴荣令次年实行。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "719cb249-c3cd-5fab-aaf2-a5c2ad7262c3"}, {"title": "林仁肇试图烧毁下蔡浮桥，风向回转后退败", "start_year": 956, "end_year": 956, "time_original": "956年八月条所记，具体交战日未载", "dynasty": "五代十国", "description": "林仁肇试图烧毁下蔡浮桥，风向回转后退败。", "phases": [], "location_name": "下蔡淮河浮桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c7e01871-2b25-5c6b-b8fb-b227029aab37"}, {"title": "张永德在浮桥外横设铁索与巨木，阻止南唐船靠近", "start_year": 956, "end_year": 956, "time_original": "956年下蔡火攻失利以后，具体日未载", "dynasty": "五代十国", "description": "张永德设置千余尺铁索，在离浮桥十余步处横截淮流，系以巨木，阻止南唐军靠近。长度和距离沿用史载单位，不未经证据换算成现代工程尺度。", "phases": [], "location_name": "下蔡淮河浮桥外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e97d30a9-faa5-5ce6-a18b-929c708166df"}, {"title": "柴荣任王朴为户部侍郎、枢密副使", "start_year": 956, "end_year": 956, "time_original": "956年九月丙午", "dynasty": "五代十国", "description": "柴荣任王朴为户部侍郎、枢密副使。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fb34e447-9dec-5492-a770-4092eca39f60"}, {"title": "李重进奏报王彦升等击败进攻盛唐的南唐军", "start_year": 956, "end_year": 956, "time_original": "956年十月癸酉奏报，具体交战日未载", "dynasty": "五代十国", "description": "李重进于十月癸酉奏报南唐军进攻盛唐，王彦升等击败对方。《资治通鉴》记斩首三千余级，《旧五代史》本纪记二千级，数量有异。癸酉是奏报日，不能直接当作交战日。", "phases": [], "location_name": "盛唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d38c98c5-b76f-5d31-998b-d73b0c214ce3"}, {"title": "柴荣令夏税六月、秋税十月起征，避免提前征收", "start_year": 956, "end_year": 956, "time_original": "956年十月丙子下诏；此后夏税六月、秋税十月起征", "dynasty": "五代十国", "description": "柴荣指出近来谷帛征敛常在收获、纺织完成前就开始，命三司此后夏税从六月起征、秋税从十月起征。《通鉴》称民间因此便利。月份沿用历史纪月，不追溯为本年六月已执行，也不误写成全国税收取消。", "phases": [], "location_name": "后周征税地区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "17b2abc8-3394-5f69-898c-7424b6bba844"}, {"title": "安审琦入朝获加守太师，随后返回襄州", "start_year": 956, "end_year": 956, "time_original": "956年十月条所记；《旧五代史》记丙子加守太师", "dynasty": "五代十国", "description": "安审琦入朝获加守太师，随后返回襄州。", "phases": [], "location_name": "襄州至后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4c593647-9060-5c8d-baf0-eac5d8bafb4e"}, {"title": "柴荣询问安审琦送行情况，主张以诚信对待地方长官", "start_year": 956, "end_year": 956, "time_original": "956年十月安审琦离京以后，具体日未载", "dynasty": "五代十国", "description": "安审琦离京后，柴荣问宰相是否送行。宰相答送至城南，安审琦感念恩遇。柴荣认为近来朝廷不以诚信待诸侯，妨碍他们效忠，主张君主先守信。这里记录君臣对话，不把“诸侯归心”写成所有地方已经完全臣服。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "932226c3-3429-505c-8466-1f06fe1e0916"}, {"title": "张永德奏报下蔡再胜：泳者夜潜锁船，周军进击", "start_year": 956, "end_year": 956, "time_original": "956年十月壬午奏报，具体夜战日未载", "dynasty": "五代十国", "description": "南唐水军再次进攻张永德。张永德夜令善游者潜入船下，以铁锁系船，再发兵进攻，南唐船不能进退，史书称溺死者很多。他于十月壬午奏报获胜。此战与先前火攻浮桥失败分开记录，未给死亡精确人数或泳者姓名。", "phases": [], "location_name": "下蔡水域", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6b9d7187-b8a3-53f1-b41b-aba1e4d93e20"}, {"title": "张永德解下金带，奖赏锁船获胜的泳者", "start_year": 956, "end_year": 956, "time_original": "956年下蔡锁船战获胜后，具体赏赐日未载", "dynasty": "五代十国", "description": "张永德解下金带，奖赏锁船获胜的泳者。", "phases": [], "location_name": "下蔡军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "62f5befc-f7be-5ae5-ac42-d9b6dfdf3d34"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_event (id, person_id, event_id, role, status)
