INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "南唐诸将请求据险截击周军，宋齐丘认为这样会加深敌意，主张放其离去，以便缓和战争。南唐随后命各将各守驻地，不得擅自出击；这只是宋齐丘的判断，不能写成双方已经达成和议。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：唐诸将请据险以邀周师，宋齐丘曰：“如此，则怨益深，不如纵之，以德于敌，则兵易解也。”乃命诸将各自守，毋得擅出击周兵。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "85fea7ea-e51c-5cfa-9a10-b47de890c993", "subject_id": "db9a1f1c-3487-51a9-b6d6-055c6a709da7", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年七月周军撤离扬州以后，八月历法条以前，具体日未载", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：唐诸将请据险以邀周师，宋齐丘曰：“如此，则怨益深，不如纵之，以德于敌，则兵易解也。”乃命诸将各自守，毋得擅出击周兵。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "eab7e863-a10a-5ca0-9362-5eb1c7751922", "subject_id": "db9a1f1c-3487-51a9-b6d6-055c6a709da7", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "person", "field_path": "description", "claim_text": "宋齐丘：反对据险截击，主张让周军离去以缓和战争。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：唐诸将请据险以邀周师，宋齐丘曰：“如此，则怨益深，不如纵之，以德于敌，则兵易解也。”乃命诸将各自守，毋得擅出击周兵。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "68104fa5-5a14-56cd-999d-fcceca76e9ef", "subject_id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "宋齐丘：反对据险截击，主张让周军离去以缓和战争。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：唐诸将请据险以邀周师，宋齐丘曰：“如此，则怨益深，不如纵之，以德于敌，则兵易解也。”乃命诸将各自守，毋得擅出击周兵。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "94779f65-961b-59bc-997b-c760e1eacf74", "subject_id": "aeb63c57-42f1-5e78-8218-d764f18a0275", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》认为停止出击使寿春围势更紧。齐王徐景达驻濠州，遥援寿州，拥兵五万；军政由陈觉决定，徐景达只在文书末尾签署。史书称其没有决战意图、将吏畏惧陈觉而不敢进言；这些评价保留出处，不外推所有人的内心。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：由是寿春之围益急。齐王景达军于濠州，遥为寿州声援，军政皆出于陈觉，景达署纸尾而已。拥兵五万，无决战意，将吏畏觉，无敢言者。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "4729d81c-19f9-51a1-a21b-9f479ecc5b05", "subject_id": "db2b3182-ebca-5f9a-8630-b6e444903644", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年寿春围攻期间，具体驻军日未载", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：由是寿春之围益急。齐王景达军于濠州，遥为寿州声援，军政皆出于陈觉，景达署纸尾而已。拥兵五万，无决战意，将吏畏觉，无敢言者。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ec38be40-4f0b-5c9e-8d52-c4461c73bee1", "subject_id": "db2b3182-ebca-5f9a-8630-b6e444903644", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "person", "field_path": "description", "claim_text": "徐景达：以齐王身份率五万兵驻濠州，签署军中文书。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：由是寿春之围益急。齐王景达军于濠州，遥为寿州声援，军政皆出于陈觉，景达署纸尾而已。拥兵五万，无决战意，将吏畏觉，无敢言者。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "47026b07-5be9-5286-8d39-4172b78be623", "subject_id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "徐景达：以齐王身份率五万兵驻濠州，签署军中文书。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·zztj-v293-y0956-p041·原文件第46行", "note": "原文：由是寿春之围益急。齐王景达军于濠州，遥为寿州声援，军政皆出于陈觉，景达署纸尾而已。拥兵五万，无决战意，将吏畏觉，无敢言者。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "50734683-d2cc-54c4-be38-30c694559e3f", "subject_id": "6c81f5f2-f983-513f-b3dc-0b4991618f35", "source_id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"subject_table": "person", "field_path": "description", "claim_text": "陈觉：掌握援军军政。", "citation": "卷293·显德三年（956年八月至十月及相关叙述）·